CREATE TABLE workflow_versions ( id INTEGER PRIMARY KEY AUTOINCREMENT, instance_id TEXT NOT NULL DEFAULT '', workflow_id TEXT NOT NULL, version_number INTEGER NOT NULL, workflow_name TEXT NOT NULL, workflow_snapshot TEXT NOT NULL, trigger TEXT NOT NULL CHECK(trigger IN ( 'partial_update', 'full_update', 'autofix' )), operations TEXT, fix_types TEXT, metadata TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(instance_id, workflow_id, version_number) )